def total_spent(expenses):
    total = 0
    for e in expenses:
        total += e["amount"]
    return total

def totals_by_category(expenses):
    totals = {}
    for e in expenses:
        totals[e["category"]] = totals.get(e["category"], 0) + e["amount"]
    return totals

def top_category(totals):
    best = None
    for name, amount in totals.items():
        if best is None or amount > totals[best]:
            best = name
    return best

