]

budget = {"rent": 800, "food": 100, "fun": 50, "transport": 25}

def totals_by_category(expenses):
    totals = {}
    for e in expenses:
        totals[e["category"]] = totals.get(e["category"], 0) + e["amount"]
    return totals

def over_budget(totals, budget):
    result = []
    for name in sorted(totals):
        limit = budget.get(name, 0)
        if totals[name] > limit:
            result.append((name, round(totals[name] - limit, 2)))
    return result

flags = over_budget(totals_by_category(expenses), budget)
if not flags:
    print("No overspend")
for name, extra in flags:
    print(f"{name} over by {extra:.2f}")
